const base='/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild';
const queries=[
 'finite subset affine open group scheme',
 'finite type group scheme quasi projective',
 'identity component group scheme irreducible',
 'component finite group scheme affine open',
 'orbit affine open semilinear Picard'
];
const results=await Promise.all(queries.map(q=>tools.exec_command({
 cmd:`"$HORIZON_BIN" search "${q}" --json`,
 workdir:base,yield_time_ms:10000,max_output_tokens:15000
})));
for(let i=0;i<results.length;i++) text(`QUERY ${queries[i]}\n${results[i].output}`);

const sib='/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge';
const root='/home/axel/LeanAlgebraicGeometry-Horizon';
const results=await Promise.all([
 tools.exec_command({cmd:"nl -ba AlgebraicJacobian/Picard/QuasiProjectiveFiniteInAffine.lean | sed -n '330,535p'",workdir:sib,yield_time_ms:10000,max_output_tokens:25000}),
 tools.exec_command({cmd:"nl -ba AlgebraicJacobian/Picard/QuasiProjectiveFiniteInAffine.lean | sed -n '535,585p'; nl -ba AlgebraicJacobian/Picard/QuasiProjectiveFiniteInAffine.lean | sed -n '700,780p'",workdir:sib,yield_time_ms:10000,max_output_tokens:16000}),
 tools.exec_command({cmd:"nl -ba .lake-packages/mathlib/Mathlib/AlgebraicGeometry/Group/Smooth.lean | sed -n '1,160p'",workdir:root,yield_time_ms:10000,max_output_tokens:15000}),
 tools.exec_command({cmd:"rg -n \"identityComponent|connectedComponent|ConnectedComponent|component.*GrpObj|irreducibleComponent|IsPreconnected.*group|IsConnected.*group\" .lake-packages/mathlib/Mathlib --glob '*.lean' | head -n 500",workdir:root,yield_time_ms:10000,max_output_tokens:20000}),
