  tools.exec_command({"cmd":"sed -n '1,240p' .claude/skills/horizon/SKILL.md","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"git status --short && git diff --cached --name-status HEAD && git diff --cached --shortstat","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"\"$HORIZON_BIN\" ps --json","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":30000})
]);
